package popcount

import "math/bits"



// Popcount returns the number of set bits across all words of xs.
func Popcount(xs []uint64) int {
	n := 0
	for len(xs) >= 8 {
		x := xs[:8:8]
		// Carry-save reduction of 8 words into weighted bit-planes.
		s1 := x[0] ^ x[1] ^ x[2]
		c1 := (x[0] & x[1]) | (x[2] & (x[0] ^ x[1]))
		s2 := x[3] ^ x[4] ^ x[5]
		c2 := (x[3] & x[4]) | (x[5] & (x[3] ^ x[4]))
		s3 := x[6] ^ x[7] ^ s1
		c3 := (x[6] & x[7]) | (s1 & (x[6] ^ x[7]))
		s := s2 ^ s3
		c := s2 & s3
		t := c1 ^ c2 ^ c3
		d := (c1 & c2) | (c3 & (c1 ^ c2))
		u := t ^ c
		v := t & c
		e := d ^ v
		f := d & v
		n += bits.OnesCount64(s) + 2*bits.OnesCount64(u) +
			4*bits.OnesCount64(e) + 8*bits.OnesCount64(f)
		xs = xs[8:]
	}
	if len(xs)&4 != 0 {
		n += bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1]) +
			bits.OnesCount64(xs[2]) + bits.OnesCount64(xs[3])
		xs = xs[4:]
	}
	if len(xs)&2 != 0 {
		n += bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1])
		xs = xs[2:]
	}
	if len(xs) != 0 {
		n += bits.OnesCount64(xs[0])
	}
	return n
}

